SELECT loan_id, account_id, date, amount, duration, payments, status
FROM loan
WHERE amount > (
    SELECT amount
    FROM loan
    ORDER BY amount
    LIMIT 1 OFFSET (
        SELECT CAST(COUNT(*) * 3 / 4 AS INTEGER) FROM loan
    )
);

SELECT DISTINCT loan.account_id, loan.amount
FROM loan
WHERE loan.amount > 100000;

